// Desktop 2.0 snapshot: src/main/resolver/ytdlpWorker.ts. Generated by scripts/import-pc-2.mjs; platform adaptations are explicit in that script.
// «Тёплый» yt-dlp: один процесс Python (resources/python) с загруженным yt-dlp отвечает на запросы
// ссылок и поиска SoundCloud. Это экономит запуск yt-dlp.exe на каждую песню (около 1,1 с)
// и повторную загрузку модулей и настроек источников. Скрипт процесса: resources/ytdlp-worker/worker.py.
//
// Если тёплый процесс не запустился или упал, резолвер работает как раньше, через yt-dlp.exe.
// Защита источников не обходится: те же запросы, что делает yt-dlp из командной строки.
import { spawn, type ChildProcessWithoutNullStreams } from 'node:child_process';
import { existsSync } from 'node:fs';
import path from 'node:path';
import { createInterface } from 'node:readline';

export interface WorkerPaths {
  python: string;
  script: string;
  /** zipapp yt-dlp (встроенный или обновлённый). */
  ytdlp: string;
  vendor: string;
  plugins?: string;
  /** Как --js-runtimes: "node:C:\\путь\\electron.exe". */
  js?: string;
  cache?: string;
  env?: Record<string, string>;
}

export type WorkerReply = { ok: true; info: Record<string, unknown> } | { ok: false; error: string };

interface Pending {
  resolve: (r: WorkerReply) => void;
  timer: ReturnType<typeof setTimeout>;
}

/** Где лежат части тёплого yt-dlp: в установленном приложении resources\..., в проекте resources/... */
export function findWorker(root: string): Omit<WorkerPaths, 'js' | 'cache' | 'env' | 'ytdlp'> & { ytdlp: string } | null {
  const res = existsSync(path.join(root, 'python')) ? root : path.join(root, 'resources');
  const p = {
    python: path.join(res, 'python', 'python.exe'),
    script: path.join(res, 'ytdlp-worker', 'worker.py'),
    ytdlp: path.join(res, 'python', 'yt-dlp.pyz'),
    vendor: path.join(res, 'python', 'vendor'),
    // Папка, в которой лежат дополнения (как --plugin-dirs у yt-dlp.exe)
    plugins: [path.join(res, 'yt-dlp-plugins')].find((x) => existsSync(x)),
  };
  return existsSync(p.python) && existsSync(p.script) && existsSync(p.ytdlp) && existsSync(p.vendor) ? p : null;
}

/** Сколько подряд падений терпим, прежде чем совсем перейти на yt-dlp.exe. */
const MAX_CRASHES = 3;

export class YtdlpWorker {
  private child: ChildProcessWithoutNullStreams | null = null;
  private ready: Promise<boolean> | null = null;
  private pending = new Map<number, Pending>();
  private seq = 0;
  private crashes = 0;
  version: string | null = null;

  constructor(
    private paths: WorkerPaths,
    private log: (m: string) => void = () => undefined,
  ) {}

  /** Работает ли тёплый процесс (или ещё можно попробовать его запустить). */
  get usable(): boolean {
    return this.crashes < MAX_CRASHES;
  }

  /** Сменить yt-dlp (после обновления): старый процесс закрывается, новый запустится при следующем запросе. */
  setYtdlp(file: string): void {
    if (file === this.paths.ytdlp) return;
    this.paths = { ...this.paths, ytdlp: file };
    this.stop();
  }

  /** Запуск заранее (при старте программы), чтобы первая песня не ждала загрузки yt-dlp. */
  start(): Promise<boolean> {
    if(process.env.MC_FIXTURES && process.env.MC_FIXTURES_MODE !== 'record') return Promise.resolve(false);
    if (this.ready) return this.ready;
    const p = this.paths;
    const args = ['-I', '-X', 'utf8', p.script, '--ytdlp', p.ytdlp, '--vendor', p.vendor];
    if (p.plugins) args.push('--plugins', p.plugins);
    if (p.js) args.push('--js', p.js);
    if (p.cache) args.push('--cache', p.cache);
    const t0 = Date.now();
    this.ready = new Promise<boolean>((resolve) => {
      let child: ChildProcessWithoutNullStreams;
      try {
        child = spawn(p.python, args, { windowsHide: true, env: { ...process.env, PYTHONIOENCODING: 'utf-8', ...p.env } });
      } catch (e) {
        this.fail(`не запустился: ${(e as Error).message}`);
        resolve(false);
        return;
      }
      this.child = child;
      const startTimer = setTimeout(() => {
        this.fail('не ответил за 30 с при запуске');
        resolve(false);
      }, 30_000);
      let stderr = '';
      child.stderr.on('data', (d: Buffer) => {
        stderr = (stderr + d.toString('utf8')).slice(-2000);
      });
      child.on('error', (e) => {
        clearTimeout(startTimer);
        this.fail(`ошибка процесса: ${e.message}`);
        resolve(false);
      });
      child.on('exit', (code) => {
        clearTimeout(startTimer);
        if (this.child !== child) return; // закрыли сами (обновление yt-dlp)
        this.fail(`процесс завершился (код ${code}) ${stderr.trim().split(/\r?\n/).at(-1) ?? ''}`);
        resolve(false);
      });
      createInterface({ input: child.stdout }).on('line', (line) => {
        let msg: { ready?: boolean; version?: string; id?: number; log?: string } & Partial<WorkerReply>;
        try {
          msg = JSON.parse(line);
        } catch {
          return;
        }
        if (msg.ready) {
          clearTimeout(startTimer);
          this.version = msg.version ?? null;
          this.log(`[yt-dlp] тёплый процесс готов за ${Date.now() - t0} мс (yt-dlp ${this.version})`);
          resolve(true);
          // Прогрев SoundCloud: первый запрос получает настройки доступа (около 4 с), пусть это будет не на песне человека
          setTimeout(() => void this.request({ op: 'search', query: 'music', limit: 1 }, 30_000), 0);
          return;
        }
        if (msg.log) this.log(`[yt-dlp] ${msg.log}`);
        if (typeof msg.id !== 'number') return;
        const w = this.pending.get(msg.id);
        if (!w) return;
        this.pending.delete(msg.id);
        clearTimeout(w.timer);
        w.resolve(msg.ok ? { ok: true, info: (msg as { info: Record<string, unknown> }).info } : { ok: false, error: String((msg as { error?: string }).error ?? 'ошибка') });
      });
    });
    return this.ready;
  }

  /** Процесс упал или не запустился: все ждущие получают ошибку, следующий запрос запустит заново. */
  private fail(why: string): void {
    this.crashes++;
    this.log(`[yt-dlp] тёплый процесс: ${why}${this.usable ? '' : '; дальше работаю через yt-dlp.exe'}`);
    const child = this.child;
    this.child = null;
    this.ready = null;
    child?.kill();
    for (const [id, w] of this.pending) {
      clearTimeout(w.timer);
      w.resolve({ ok: false, error: 'тёплый процесс yt-dlp перезапускается' });
      this.pending.delete(id);
    }
  }

  stop(): void {
    const child = this.child;
    this.child = null;
    this.ready = null;
    if (child) {
      try {
        child.stdin.write('{"op":"quit"}\n');
      } catch {
        // уже закрыт
      }
      setTimeout(() => child.kill(), 2000).unref();
    }
  }

  /**
   * Запрос к тёплому процессу. null: процесс недоступен (тогда вызывающий берёт yt-dlp.exe).
   * signal: запрос больше не нужен (ответ просто не ждём).
   */
  async request(req: { op: 'stream' | 'search'; url?: string; query?: string; profile?: string; limit?: number }, timeoutMs: number, signal?: AbortSignal): Promise<WorkerReply | null> {
    if (!this.usable) return null;
    if (!(await this.start()) || !this.child) return null;
    const id = ++this.seq;
    return new Promise<WorkerReply>((resolve) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        resolve({ ok: false, error: `yt-dlp не ответил за ${Math.round(timeoutMs / 1000)} секунд` });
      }, timeoutMs);
      this.pending.set(id, { resolve, timer });
      signal?.addEventListener(
        'abort',
        () => {
          if (!this.pending.delete(id)) return;
          clearTimeout(timer);
          resolve({ ok: false, error: 'отменено' });
        },
        { once: true },
      );
      try {
        this.child!.stdin.write(`${JSON.stringify({ id, ...req })}\n`);
      } catch (e) {
        this.pending.delete(id);
        clearTimeout(timer);
        resolve({ ok: false, error: `не удалось отправить запрос: ${(e as Error).message}` });
      }
    });
  }
}
